SELECT ROUND(SUM(oi.quantity * oi.unit_price), 2) AS gross_revenue
FROM orders o JOIN order_items oi ON oi.order_id = o.id
WHERE o.status = 'completed' AND o.order_date >= '2024-01-01' AND o.order_date < '2025-01-01';

SELECT COUNT(DISTINCT customer_id) AS active_customers
FROM orders
WHERE status = 'completed' AND order_date >= '2025-01-01' AND order_date < '2026-01-01';

SELECT EXTRACT(YEAR FROM signup_date)::int AS year, COUNT(*) AS new_customers
FROM customers_safe
GROUP BY 1 ORDER BY 1;
